#!/bin/bash
# Build the client patch MPQs from YOUR OWN client files. Nothing proprietary ships with this repo.
#   ORIG     = directory with the original files extracted from your client (same relative paths,
#              e.g. ORIG/Interface/GlueXML/CharacterCreate.lua, ORIG/DBFilesClient/SkillLine.dbc)
#   GEN      = directory with the DBCs generated by tools/ (CharacterAdvancement.dbc, ChrSpecs.dbc,
#              CharacterAdvancementEssence.dbc, CharacterAdvancementTabTypes.dbc)
#   OUT      = output directory for patch-ZZ*.MPQ
# Usage: ORIG=... GEN=... OUT=... client/build/build_patches.sh
# Internal MPQ paths MUST use backslashes, or the client silently ignores the file.
set -euo pipefail
here="$(cd "$(dirname "$0")/.." && pwd)"; tools="$here/../tools"
: "${ORIG:?set ORIG}"; : "${GEN:?set GEN}"; : "${OUT:?set OUT}"
MK="${MPQ_TOOLS:-$here/build}/mkpatch"; export LD_LIBRARY_PATH="${MPQ_TOOLS:-$here/build}"
work="$(mktemp -d)"; trap 'rm -rf "$work"' EXIT
cp -r "$ORIG/." "$work/"
find "$work/Interface" -name '*.lua' -exec sed -i 's/\r$//' {} +   # the diffs are LF; some originals are CRLF
for d in "$here"/diffs/*.diff; do (cd "$work" && patch -p1 --binary -s < "$d"); done
for j in "$here"/dbc-deltas/*.delta.json; do
  n="$(basename "$j" .delta.json)"
  python3 "$tools/dbcdelta.py" apply "$work/DBFilesClient/$n.dbc" "$j" "$work/DBFilesClient/$n.dbc"
done
mkdir -p "$OUT"
pack() { local out="$1"; shift; rm -f "$out"; "$MK" "$out" "$@" >/dev/null; echo "built $out"; }
pack "$OUT/patch-ZZS.MPQ" \
  "$GEN/CharacterAdvancementTabTypes.dbc" 'DBFilesClient\CharacterAdvancementTabTypes.dbc' \
  "$work/DBFilesClient/CharBaseInfo.dbc" 'DBFilesClient\CharBaseInfo.dbc' \
  "$work/DBFilesClient/ChrRaces.dbc" 'DBFilesClient\ChrRaces.dbc' \
  "$work/DBFilesClient/SkillLine.dbc" 'DBFilesClient\SkillLine.dbc' \
  "$work/DBFilesClient/SkillLineAbility.dbc" 'DBFilesClient\SkillLineAbility.dbc' \
  "$work/DBFilesClient/SkillRaceClassInfo.dbc" 'DBFilesClient\SkillRaceClassInfo.dbc' \
  "$work/Interface/GlueXML/CharacterCreate.lua" 'Interface\GlueXML\CharacterCreate.lua'
pack "$OUT/patch-ZZV.MPQ" "$work/Interface/SharedXML/AtlasInfo.lua" 'Interface\SharedXML\AtlasInfo.lua'
pack "$OUT/patch-ZZW.MPQ" \
  "$GEN/CharacterAdvancement.dbc" 'DBFilesClient\CharacterAdvancement.dbc' \
  "$GEN/CharacterAdvancementEssence.dbc" 'DBFilesClient\CharacterAdvancementEssence.dbc' \
  "$GEN/ChrSpecs.dbc" 'DBFilesClient\ChrSpecs.dbc'
pack "$OUT/patch-ZZX.MPQ" "$work/Interface/FrameXML/Util/CharacterAdvancementUtil.lua" 'Interface\FrameXML\Util\CharacterAdvancementUtil.lua'
pack "$OUT/patch-ZZY.MPQ" \
  "$work/Interface/AddOns/Ascension_Collections/Collections.lua" 'Interface\AddOns\Ascension_Collections\Collections.lua' \
  "$work/Interface/FrameXML/Util/GlobalOverwrites.lua" 'Interface\FrameXML\Util\GlobalOverwrites.lua'
pack "$OUT/patch-ZZZ.MPQ" \
  "$work/Interface/FrameXML/MainMenuBarMicroButtons.lua" 'Interface\FrameXML\MainMenuBarMicroButtons.lua' \
  "$work/Interface/FrameXML/UIParent.lua" 'Interface\FrameXML\UIParent.lua'
echo "Install the MPQs into the client's Data folder ONLY with the game closed."
